const fs = require('fs');
const path = require('path');

const rootDir = path.resolve(__dirname, '..');
const args = parseArgs(process.argv.slice(2));
const outDir = path.resolve(rootDir, args.out || 'offline-chat');
const modelDir = args.models ? path.resolve(args.models) : null;
const vendorFile = args.vendor ? path.resolve(args.vendor) : null;

function parseArgs(values) {
    const parsed = {};

    for (let i = 0; i < values.length; i++) {
        const value = values[i];
        if (!value.startsWith('--')) {
            continue;
        }

        const key = value.slice(2);
        parsed[key] = values[i + 1] && !values[i + 1].startsWith('--') ? values[++i] : true;
    }

    return parsed;
}

function ensureDir(target) {
    fs.mkdirSync(target, { recursive: true });
}

function copyFile(source, target) {
    ensureDir(path.dirname(target));
    fs.copyFileSync(source, target);
}

function copyDirectory(source, target) {
    ensureDir(target);

    for (const entry of fs.readdirSync(source, { withFileTypes: true })) {
        const sourcePath = path.join(source, entry.name);
        const targetPath = path.join(target, entry.name);

        if (entry.isDirectory()) {
            copyDirectory(sourcePath, targetPath);
        } else {
            copyFile(sourcePath, targetPath);
        }
    }
}

function cleanOutputDirectory() {
    ensureDir(outDir);

    for (const entry of fs.readdirSync(outDir, { withFileTypes: true })) {
        if (entry.name === 'models' && !modelDir) {
            continue;
        }

        if (entry.name === 'vendor' && !vendorFile) {
            continue;
        }

        fs.rmSync(path.join(outDir, entry.name), { recursive: true, force: true });
    }
}

function copyOfflineIndex() {
    let html = fs.readFileSync(path.join(rootDir, 'chat.html'), 'utf8')
        .replace('<body class="chat-page">', '<body class="chat-page chat-offline-bundle">')
        .replace(/\s*<header>[\s\S]*?<\/header>\s*/, '\n')
        .replace(/\s*<footer role="contentinfo">[\s\S]*?<\/footer>\s*/, '\n')
        .replace(/href="chat\.html"/g, 'href="index.html"')
        .replace(/https:\/\/asd123\.ai\/chat/g, 'index.html')
        .replace(
            /<script type="module" src="scripts\/chat-app\.js[^"]*"><\/script>/,
            '<script>window.asd123OfflineBundle = true;</script>\n    <script src="vendor/ort-wasm-paths.js"></script>\n    <script src="vendor/ort.webgpu.bundle.iife.js"></script>\n    <script src="vendor/transformers.iife.js"></script>\n    <script src="scripts/chat-offline-bundle.js"></script>'
        );

    html = html.replace(
        '            </section>\n\n            <section class="chat-shell"',
        `                <div class="chat-offline-theme" aria-label="Theme">
                    <span class="chat-offline-theme-label">Theme</span>
                    <label class="toggle-switch" style="transform: scale(0.8);">
                        <input type="checkbox" id="theme-toggle">
                        <span class="toggle-slider"></span>
                    </label>
                </div>
            </section>

            <section class="chat-shell"`
    );

    html = html.replace(
        '                        <input id="fileInput" type="file" accept="image/*,.txt,.md,.markdown,.pdf,.docx" multiple hidden>',
        `                        <input id="fileInput" type="file" accept="image/*,.txt,.md,.markdown,.pdf,.docx" multiple hidden>
                        <input id="folderInput" type="file" webkitdirectory directory multiple hidden>`
    );

    fs.writeFileSync(path.join(outDir, 'index.html'), html);
}

function stripExports(source) {
    return source
        .replace(/\n?export\s*\{[\s\S]*?\};?\s*$/m, '\n')
        .replace(/\n?export\s*\{[^}]*\};?\s*/g, '\n');
}

function stripImports(source) {
    return source
        .replace(/import\s*\{[\s\S]*?\}\s*from\s*['"][^'"]+['"];\s*/g, '')
        .replace(/^import\s+[^;]+;\s*/gm, '');
}

function readScript(file) {
    return fs.readFileSync(path.join(rootDir, 'scripts', file), 'utf8');
}

function wrapScriptModule(file, exportedNames) {
    const body = stripExports(readScript(file));
    const assignments = exportedNames
        .map(name => `globalThis.${name} = ${name};`)
        .join('\n');

    return `\n;(() => {\n${body}\n${assignments}\n})();\n`;
}

function buildOfflineBundle() {
    const chatApp = stripImports(readScript('chat-app.js'));
    const bundle = [
        '/* ASD123.ai offline chat bundle. Generated by tools/package-chat-offline.js. */',
        wrapScriptModule('chat-models.js', [
            'CONTEXT_WINDOWS',
            'MODEL_REGISTRY',
            'getModelConfig',
            'getContextLabel',
            'getModelOptionLabel',
            'getContextOptionLabel',
            'clampContextWindow'
        ]),
        wrapScriptModule('chat-storage.js', ['ChatStorage']),
        wrapScriptModule('chat-files.js', ['ChatFileProcessor']),
        wrapScriptModule('chat-offline.js', ['OfflineModelResolver']),
        `\n;(() => {\nconst {\n    CONTEXT_WINDOWS,\n    MODEL_REGISTRY,\n    clampContextWindow,\n    getContextOptionLabel,\n    getContextLabel,\n    getModelOptionLabel,\n    getModelConfig,\n    ChatStorage,\n    ChatFileProcessor,\n    OfflineModelResolver\n} = globalThis;\n${chatApp}\n})();\n`
    ].join('\n');

    fs.writeFileSync(path.join(outDir, 'scripts', 'chat-offline-bundle.js'), bundle);
}

function patchLocalTransformersRuntime(source) {
    return source
        .replace(/from\s*["']onnxruntime-web\/webgpu["']/g, 'from "./ort.webgpu.bundle.min.mjs"')
        .replace(/from\s*["']onnxruntime-common["']/g, 'from "./ort.webgpu.bundle.min.mjs"');
}

function parseExportSpec(spec) {
    const trimmed = spec.trim();
    if (!trimmed) {
        return null;
    }

    const aliased = trimmed.match(/^([A-Za-z_$][\w$]*)\s+as\s+([A-Za-z_$][\w$]*)$/);
    if (aliased) {
        return {
            local: aliased[1],
            exported: aliased[2]
        };
    }

    return {
        local: trimmed,
        exported: trimmed
    };
}

function convertEsmExportToGlobal(source, globalName) {
    const withoutSourceMap = source.replace(/\n?\/\/# sourceMappingURL=.*\s*$/m, '');
    const exportMatch = withoutSourceMap.match(/export\s*\{([\s\S]*?)\};?\s*$/);

    if (!exportMatch) {
        return withoutSourceMap;
    }

    const exportObject = exportMatch[1]
        .split(',')
        .map(parseExportSpec)
        .filter(Boolean)
        .map(item => `    ${JSON.stringify(item.exported)}: ${item.local}`)
        .join(',\n');
    const globalAssignment = `\nglobalThis.${globalName} = {\n${exportObject}\n};\n`;

    return `${withoutSourceMap.slice(0, exportMatch.index)}${globalAssignment}`;
}

function createOrtIife(source) {
    const importMeta = 'globalThis.__ortWebgpuImportMeta';
    return [
        'globalThis.__ortWebgpuImportMeta = { url: document.currentScript?.src || location.href };',
        convertEsmExportToGlobal(source.replace(/import\.meta/g, importMeta), 'ORT_WEBGPU')
    ].join('\n');
}

function createTransformersIife(source) {
    const importMeta = 'globalThis.__transformersImportMeta';
    const patched = source
        .replace(/import\s+\*\s+as\s+ONNX_WEB\s+from\s*["']onnxruntime-web\/webgpu["'];?\s*/g, 'const ONNX_WEB = globalThis.ORT_WEBGPU;\n')
        .replace(/import\s*\{\s*Tensor\s*\}\s*from\s*["']onnxruntime-common["'];?\s*/g, 'const { Tensor } = globalThis.ORT_WEBGPU;\n')
        .replace(/import\.meta/g, importMeta);

    return [
        'globalThis.__transformersImportMeta = { url: document.currentScript?.src || location.href };',
        convertEsmExportToGlobal(patched, 'Transformers')
    ].join('\n');
}

function prepareOfflineVendor() {
    const vendorDir = path.join(outDir, 'vendor');
    const ortBundle = path.join(vendorDir, 'ort.webgpu.bundle.min.mjs');
    const localRuntime = path.join(vendorDir, 'transformers.local.mjs');
    const ortIife = path.join(vendorDir, 'ort.webgpu.bundle.iife.js');
    const transformersIife = path.join(vendorDir, 'transformers.iife.js');

    if (!fs.existsSync(ortBundle)) {
        return false;
    }

    fs.writeFileSync(ortIife, createOrtIife(fs.readFileSync(ortBundle, 'utf8')));

    const candidates = [
        path.join(vendorDir, 'transformers.web.js'),
        path.join(vendorDir, 'transformers.web.min.js'),
        path.join(vendorDir, 'transformers.min.js')
    ];

    for (const candidate of candidates) {
        if (!fs.existsSync(candidate)) {
            continue;
        }

        const source = fs.readFileSync(candidate, 'utf8');
        const patched = patchLocalTransformersRuntime(source);
        if (patched !== source) {
            fs.writeFileSync(localRuntime, patched);
            fs.writeFileSync(transformersIife, createTransformersIife(source));
            return true;
        }
    }

    return fs.existsSync(localRuntime) && fs.existsSync(transformersIife);
}

function writeOrtWasmPaths() {
    const vendorDir = path.join(outDir, 'vendor');
    const wasmPath = path.join(vendorDir, 'ort-wasm-simd-threaded.asyncify.wasm');
    const mjsPath = path.join(vendorDir, 'ort-wasm-simd-threaded.asyncify.mjs');
    const target = path.join(vendorDir, 'ort-wasm-paths.js');

    ensureDir(vendorDir);

    if (!fs.existsSync(wasmPath)) {
        fs.writeFileSync(target, 'window.asd123OrtWasmPaths = null;\n');
        return false;
    }

    const payload = {
        wasm: `data:application/wasm;base64,${fs.readFileSync(wasmPath).toString('base64')}`
    };

    if (fs.existsSync(mjsPath)) {
        payload.mjs = `data:text/javascript;base64,${fs.readFileSync(mjsPath).toString('base64')}`;
    }

    fs.writeFileSync(
        target,
        `window.asd123OrtWasmPaths = ${JSON.stringify(payload)};\n`
    );
    return true;
}

function writeReadme() {
    const readme = `<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ASD123.ai Local Chat Offline Bundle</title>
    <style>
        body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; line-height: 1.6; max-width: 820px; margin: 48px auto; padding: 0 24px; }
        code { background: #f1f1ec; padding: 2px 6px; border-radius: 4px; }
    </style>
</head>
<body>
    <h1>ASD123.ai Local Chat Offline Bundle</h1>
    <p>Open <code>index.html</code> in a Chromium-based browser with WebGPU support.</p>
    <p>Click <strong>Load Model</strong>. The app first tries the bundled <code>models</code> folder. If the browser blocks direct file access, it will ask once for access to this <code>offline-chat</code> folder or the included <code>models</code> folder.</p>
    <p>Expected model layout examples:</p>
    <ul>
        <li><code>models/onnx-community--gemma-4-E2B-it-ONNX/config.json</code></li>
        <li><code>models/onnx-community/gemma-4-E2B-it-ONNX/config.json</code></li>
    </ul>
    <p>No executable or local server is required. For full offline use, this bundle needs <code>vendor/transformers.iife.js</code>, <code>vendor/ort.webgpu.bundle.iife.js</code>, <code>vendor/ort-wasm-paths.js</code>, and the selected model files under <code>models</code>.</p>
</body>
</html>
`;
    fs.writeFileSync(path.join(outDir, 'README.html'), readme);
}

function main() {
    cleanOutputDirectory();

    copyOfflineIndex();
    copyFile(path.join(rootDir, 'styles', 'main.css'), path.join(outDir, 'styles', 'main.css'));
    copyFile(path.join(rootDir, 'styles', 'components.css'), path.join(outDir, 'styles', 'components.css'));

    [
        'shared.js',
        'chat-app.js',
        'chat-files.js',
        'chat-models.js',
        'chat-offline.js',
        'chat-storage.js'
    ].forEach(file => {
        copyFile(path.join(rootDir, 'scripts', file), path.join(outDir, 'scripts', file));
    });
    buildOfflineBundle();

    ensureDir(path.join(outDir, 'models'));

    if (modelDir) {
        if (!fs.existsSync(modelDir)) {
            throw new Error(`Model directory not found: ${modelDir}`);
        }
        copyDirectory(modelDir, path.join(outDir, 'models'));
    }

    if (vendorFile) {
        if (!fs.existsSync(vendorFile)) {
            throw new Error(`Vendor file not found: ${vendorFile}`);
        }
        copyFile(vendorFile, path.join(outDir, 'vendor', 'transformers.min.js'));
    }

    const hasLocalVendor = prepareOfflineVendor();
    const hasLocalWasm = writeOrtWasmPaths();

    writeReadme();

    console.log(`Offline chat bundle created at ${outDir}`);
    if (!hasLocalVendor) {
        console.log('Note: add a local Transformers.js browser runtime and ONNX WebGPU bundle to offline-chat/vendor for full offline use.');
    }
    if (!hasLocalWasm) {
        console.log('Note: add ONNX Runtime WASM files to offline-chat/vendor for full offline use.');
    }
    if (!modelDir && !fs.existsSync(path.join(outDir, 'models'))) {
        console.log('Note: pass --models /path/to/model-root to include model files.');
    }
}

main();
